{"command":"set -euo pipefail
REPO='edburns/dd-3061974-05-cargotracker-linux'; PR=9; HEAD='09ad723ecc5b879fab69d47e85f576429920ea02'; REVIEW_ID=5170950935
PR_JSON=$(gh pr view "$PR" -R "$REPO" --json state,isDraft,baseRefName,headRefOid,mergeable,statusCheckRollup)
printf '%s\n' "$PR_JSON" | jq .
ACTUAL_HEAD=$(printf '%s' "$PR_JSON" | jq -r '.headRefOid'); ACTUAL_BASE=$(printf '%s' "$PR_JSON" | jq -r '.baseRefName'); MERGEABLE=$(printf '%s' "$PR_JSON" | jq -r '.mergeable')
[ "$ACTUAL_HEAD" = "$HEAD" ] || { echo "SHEPHERD FAILED: PR head changed from reviewed head"; exit 1; }
[ "$ACTUAL_BASE" = 'experiment/shepherd-control' ] || { echo "SHEPHERD FAILED: unexpected base $ACTUAL_BASE"; exit 1; }
[ "$ACTUAL_BASE" != main ] || { echo 'SHEPHERD FAILED: base is main'; exit 1; }
[ "$MERGEABLE" != CONFLICTING ] || { echo 'SHEPHERD FAILED: PR has merge conflicts'; exit 1; }
REVIEW=$(gh api "/repos/$REPO/pulls/$PR/reviews/$REVIEW_ID")
printf '%s' "$REVIEW" | jq -e --arg head "$HEAD" 'select(.commit_id == $head) | select((.user.login // "") | test("^copilot-pull-request-reviewer(\\[bot\\])?$"; "i"))' >/dev/null
TOO_MANY=$(printf '%s' "$REVIEW" | jq 'select((.body // "") | test("wasn.t able to review"; "i")) | select((.body // "") | test("maximum number of files"; "i"))')
[ -z "$TOO_MANY" ] || { echo 'SHEPHERD FAILED: Copilot too-many-files refusal'; exit 1; }
THREADS=$(gh api graphql -F owner='edburns' -F name='dd-3061974-05-cargotracker-linux' -F number="$PR" -f query='query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name){pullRequest(number:$number){reviewThreads(first:100){nodes{id isResolved comments(first:10){nodes{databaseId author{login}}}}}}}}' --jq '.data.repository.pullRequest.reviewThreads.nodes')
UNRESOLVED=$(printf '%s' "$THREADS" | jq '[.[] | select(.isResolved == false)] | length')
printf 'FINAL_GATES head=%s base=%s mergeable=%s unresolved=%s\n' "$ACTUAL_HEAD" "$ACTUAL_BASE" "$MERGEABLE" "$UNRESOLVED"
[ "$UNRESOLVED" -eq 0 ] || { echo 'SHEPHERD FAILED: unresolved review threads remain'; exit 1; }","description":"Enforce final PR merge gates","initial_wait":120,"mode":"sync"}

